  if (input[0] != SLOT_MAGIC_0 || input[1] != SLOT_MAGIC_1) return SlotStatus::BadMagic;
  if (input[2] != SLOT_VERSION) return SlotStatus::IncompatibleVersion;
  if (protocol::readU32Le(input + 12) != protocol::crc32c(input, 12)) return SlotStatus::HeaderCrcMismatch;

  const uint8_t flags = input[3];
  const uint16_t packetSize = protocol::readU16Le(input + 4);
  const bool hasPacket = (flags & SLOT_FLAG_PACKET) != 0;
  if (packetSize > protocol::MAX_PACKET_SIZE || hasPacket != (packetSize > 0)) return SlotStatus::InvalidLength;

  slot->flags = flags;
  slot->sequence = protocol::readU32Le(input + 8);
  slot->packet = protocol::PacketView();
  slot->packetStatus = protocol::PacketStatus::Ok;
