  slot->packetStatus = protocol::decodePacket(input + SLOT_HEADER_SIZE, packetSize, &slot->packet);
  return slot->packetStatus == protocol::PacketStatus::Ok ? SlotStatus::Ok : SlotStatus::PacketInvalid;
